test("status and headers", () => {
  expect(res.status).to.equal(200);
  expect(res.getStatus()).to.equal(200);
  expect(res.statusText).to.equal("OK");
  expect(res.getHeader("X-Request-Id")).to.equal("r-1");
  expect(res.headers["content-type"]).to.equal("application/json");
  expect(res.getResponseTime()).to.equal(42);
});
test("body", () => {
  expect(res.body.items[0].id).to.equal(1);
  expect(res.getBody().total).to.equal(2);
  expect(res("items[1].name")).to.equal("b");
  expect(res("items.id")).to.eql([1, 2]);
  expect(res("..name")).to.eql(["a", "b"]);
  expect(res("total")).to.equal(2);
});
test("expect(res).to.have.status", () => expect(res).to.have.status(200));
